function drawWave(xpos, ypos, freq, amp, ang, step, len, thick) {
  push();
  translate(xpos, ypos);
  rotate(ang);
  const strokeCol = generateColor();
  const fillCol   = generateColor();
  strokeWeight(thick);
  stroke(strokeCol);
  fill(fillCol);
	noFill();
  const phase = 0.025*(frameCount * speedMult);

  beginShape();
  for (let xx = -len / 2; xx <= len / 2; xx += step) {
    amp -= 1;
    const yy = amp * cos(xx*freq + phase);
    curveVertex(xx, yy);
  }

  endShape();
  pop();
}
function drawSquareWave(xpos, ypos, freq, amp, ang, step, len, thick) {
  push();
  translate(xpos, ypos);
  rotate(ang);

  const strokeCol = generateColor();
  const fillCol   = generateColor();
  strokeWeight(thick);
  stroke(strokeCol);
  noFill();  

  const phase = 0.025 * (frameCount * speedMult);

  beginShape();
  let prevY = null;

  for (let xx = -len / 2; xx <= len / 2; xx += step) {
    const s  = cos(xx * freq + phase);
    const yy = (s >= 0) ? amp : -amp;

    if (prevY === null) {
      vertex(xx, yy);
    } else {
      if (yy !== prevY) {
        vertex(xx, prevY);
        vertex(xx, yy);
      } else {
        vertex(xx, yy);
      }
    }
    prevY = yy;
  }

  endShape();
  pop();
}


function generateColor() {
  let myColor = color(random(colors));
  myColor.setAlpha(random(50, 100));
  return myColor;
}


